import sys
from collections import defaultdict

def is_valid_date(day, month, year):
    if year < 2013 or year > 2015:
        return False
    if month < 1 or month > 12:
        return False
    if day < 1:
        return False
    if month == 2:
        return day <= 28
    if month in {4, 6, 9, 11}:
        return day <= 30
    return day <= 31

def find_apocalypse_date(prophesy):
    date_count = defaultdict(int)
    n = len(prophesy)

    for i in range(n - 10 + 1):
        if prophesy[i+2] == '-' and prophesy[i+5] == '-':
            day = int(prophesy[i:i+2])
            month = int(prophesy[i+3:i+5])
            year = int(prophesy[i+6:i+10])
            if is_valid_date(day, month, year):
                date_count[(day, month, year)] += 1

    apocalypse_date = max(date_count, key=date_count.get)
    return f"{apocalypse_date[0]:02d}-{apocalypse_date[1]:02d}-{apocalypse_date[2]}"

prophesy = sys.stdin.read().strip()
print(find_apocalypse_date(prophesy))
